import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class OrderService {
    // Static logger instance - created once per class
    private static final Logger logger = LoggerFactory.getLogger(OrderService.class);

    public void processOrder(Long orderId, String customerName) {
        logger.info("Processing order {} for customer {}", orderId, customerName);

        try {
            // Business logic here
            var order = fetchOrder(orderId);
            logger.debug("Order details: {}", order); // Only logs if DEBUG enabled
        } catch (Exception e) {
            // Exception logging with stack trace
            logger.error("Failed to process order {}", orderId, e);
            throw e;
        }

        logger.info("Order {} completed successfully", orderId);
    }
}

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class UserService {
    // Standard logger declaration - one per class
    private static final Logger logger = LoggerFactory.getLogger(UserService.class);

    public void registerUser(String email, String username) {
        logger.info("Registering new user: {}", email);

        // Debug logs for detailed diagnostics
        logger.debug("Username: {}, validation started", username);

        if (username.length() < 3) {
            logger.warn("Username too short for {}: {} chars", email, username.length());
            throw new IllegalArgumentException("Username must be 3+ characters");
        }

        try {
            saveToDatabase(email, username);
            logger.info("User {} registered successfully", email);
        } catch (Exception e) {
            // Exception as last parameter prints stack trace
            logger.error("Failed to register user {}", email, e);
            throw e;
        }
    }
}

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;
import org.springframework.stereotype.Component;
import jakarta.servlet.*;
import java.util.UUID;

@Component
public class RequestIdFilter implements Filter {
    private static final Logger logger = LoggerFactory.getLogger(RequestIdFilter.class);

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
            throws java.io.IOException, ServletException {
        // Generate unique ID for this request
        var requestId = UUID.randomUUID().toString();
        MDC.put("requestId", requestId);
        MDC.put("userId", extractUserId(request)); // From auth token

        try {
            logger.info("Request started"); // Automatically includes requestId
            chain.doFilter(request, response);
            logger.info("Request completed");
        } finally {
            // CRITICAL: Clear MDC to avoid leaking to next request on this thread
            MDC.clear();
        }
    }
}

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

@Service
public class ProductService {
    // Standard logger declaration - appears in every class that logs
    private static final Logger logger = LoggerFactory.getLogger(ProductService.class);

    private final ProductRepository repository;

    public ProductService(ProductRepository repository) {
        this.repository = repository;
        logger.info("ProductService initialized"); // Logs at startup
    }

    public Product findById(Long productId) {
        logger.debug("Searching for product with ID: {}", productId);

        var product = repository.findById(productId)
            .orElseThrow(() -> {
                logger.error("Product not found: {}", productId);
                return new ProductNotFoundException(productId);
            });

        logger.info("Found product: {} - {}", product.id(), product.name());
        return product;
    }
}

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class OrderProcessor {
    private static final Logger logger = LoggerFactory.getLogger(OrderProcessor.class);

    public void processOrders(List<Order> orders) {
        for (var order : orders) {
            // BAD: String concatenation - always executes even if DEBUG disabled
            logger.debug("Processing order: " + order.getId() + 
                        ", customer: " + order.getCustomer().getName() +
                        ", total: " + order.getTotal());
            // Cost: 3 toString() calls, 3+ string concatenations, string object allocation
            // Happens on EVERY iteration even when DEBUG is OFF

            // GOOD: Placeholders - arguments untouched if DEBUG disabled
            logger.debug("Processing order: {}, customer: {}, total: {}",
                        order.getId(), order.getCustomer(), order.getTotal());
            // Cost: Almost zero if DEBUG is OFF - just one level check
            // Only builds string if DEBUG is ON

            processOrder(order);
        }
    }
}
